package tri_lion.health.dto.request.user;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.List;
public final class UserRequests {private UserRequests(){} public record AgreementsRequest(@NotEmpty List<@Valid Agreement> agreements){} public record Agreement(@NotBlank String type,boolean agreed){} public record OnboardingRequest(String name,@Past LocalDate birthDate,@NotBlank String gender,@DecimalMin("1") BigDecimal heightCm,@DecimalMin("1") BigDecimal weightKg,@NotEmpty List<String> goals,BigDecimal targetWeightKg,@NotBlank String activityLevel,@NotEmpty List<String> availableExerciseDays,@Min(5) @Max(300) Integer availableExerciseMinutes,List<String> dietaryPreferences,List<String> allergies,List<String> dislikedFoods,List<@Valid Injury> injuries){} public record Injury(@NotBlank String bodyPart,String description){} }
